"""Query plan analyzer for BigQuery jobs."""

import json
from typing import List, Dict, Any


def analyze_plan(job_stages: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Analyze query plan stages for bottlenecks."""
    total_slot_ms = sum(s.get('slot_ms', 0) for s in job_stages)
    max_slot_ms = max(s.get('slot_ms', 0) for s in job_stages)

    skew_ratio = max_slot_ms / (total_slot_ms / len(job_stages)) if job_stages else 0

    bottlenecks = []
    for stage in job_stages:
        if stage.get('slot_ms', 0) > total_slot_ms * 0.5:
            bottlenecks.append({
                'stage_id': stage['stage_id'],
                'name': stage['name'],
                'pct_of_total': stage['slot_ms'] / total_slot_ms * 100
            })

    return {
        'total_stages': len(job_stages),
        'total_slot_ms': total_slot_ms,
        'skew_ratio': round(skew_ratio, 2),
        'health': 'critical' if skew_ratio > 5 else 'warning' if skew_ratio > 2 else 'healthy',
        'bottleneck_stages': bottlenecks,
    }

"""Schema change detection for BigQuery tables."""

from typing import List, Dict


def diff_schemas(old_schema: List[Dict], new_schema: List[Dict]) -> Dict:
    """Compare two schema definitions and return differences."""
    old_fields = {f['name']: f for f in old_schema}
    new_fields = {f['name']: f for f in new_schema}

    added = [f for name, f in new_fields.items() if name not in old_fields]
    removed = [f for name, f in old_fields.items() if name not in new_fields]

    modified = []
    for name in set(old_fields) & set(new_fields):
        if old_fields[name] != new_fields[name]:
            modified.append({
                'field': name,
                'old': old_fields[name],
                'new': new_fields[name]
            })

    has_breaking = len(removed) > 0 or any(
        m['old'].get('type') != m['new'].get('type') for m in modified
    )

    return {
        'added': added,
        'removed': removed,
        'modified': modified,
        'has_breaking_changes': has_breaking,
        'severity': 'critical' if has_breaking else 'info'
    }
